const listProviderProfiles = `-- name: ListProviderProfiles :many
SELECT p.id, p.tenant_organization_id, p.provider_type, p.status, p.network_tier,
       p.contracted_from, p.contracted_to, p.notes, p.created_at, p.row_version,
       o.display_name AS organization_name
  FROM provider.provider_profile p
  JOIN directory.tenant_organization t
    ON t.tenant_id = p.tenant_id AND t.id = p.tenant_organization_id
  JOIN directory.organization o ON o.id = t.organization_id
 WHERE p.tenant_id = $1
   AND ($2::uuid[] IS NULL
        OR p.tenant_organization_id = ANY($2::uuid[]))
   AND ($3::text IS NULL OR p.provider_type = $3::text)
   AND ($4::text IS NULL OR p.status = $4::text)
   AND ($5::text IS NULL OR p.network_tier = $5::text)
   -- The caller escapes the user's own wildcards (domain.LikePattern), so the default
   -- backslash escape character makes '%' and '_' literal characters here.
   AND ($6::text IS NULL OR o.display_name ILIKE $6::text)
   AND ($7::timestamptz IS NULL
        OR (p.created_at, p.id) < ($7::timestamptz, $8::uuid))
 ORDER BY p.created_at DESC, p.id DESC
 LIMIT $9
`

type ListProviderProfilesParams struct {
	TenantID        uuid.UUID
	ScopeIds        []uuid.UUID
	ProviderType    *string
	Status          *string
	NetworkTier     *string
	Q               *string
	CursorCreatedAt *time.Time
	CursorID        uuid.NullUUID
	PageSize        int32
}

type ListProviderProfilesRow struct {
	ID                   uuid.UUID
	TenantOrganizationID uuid.UUID
	ProviderType         string
	Status               string
	NetworkTier          *string
	ContractedFrom       pgtype.Date
	ContractedTo         pgtype.Date
	Notes                *string
	CreatedAt            time.Time
	RowVersion           int64
	OrganizationName     string
}

// Keyset pagination on (created_at DESC, id DESC); the caller asks for limit+1 rows to
// learn whether a next page exists.
func (q *Queries) ListProviderProfiles(ctx context.Context, arg ListProviderProfilesParams) ([]ListProviderProfilesRow, error) {
	rows, err := q.db.Query(ctx, listProviderProfiles,
		arg.TenantID,
		arg.ScopeIds,
		arg.ProviderType,
		arg.Status,
		arg.NetworkTier,
		arg.Q,
		arg.CursorCreatedAt,
		arg.CursorID,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListProviderProfilesRow
	for rows.Next() {
		var i ListProviderProfilesRow
		if err := rows.Scan(
			&i.ID,
			&i.TenantOrganizationID,
			&i.ProviderType,
			&i.Status,
			&i.NetworkTier,
			&i.ContractedFrom,
			&i.ContractedTo,
			&i.Notes,
			&i.CreatedAt,
			&i.RowVersion,
			&i.OrganizationName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

